import {currentUser,clearAuthSession} from './auth-session.js';
import {loginURL} from './auth-routing.js';
import {esc,size,number,date,uptime,badge,empty,serviceRow,renderTasks,renderEvents} from './admin-view.js';
const $=selector=>document.querySelector(selector),pageSize=30;
let view='overview',taskOffset=0,eventOffset=0,busy=false,pending=false,controller=null,sequence=0,authorized=false,active=true,timer;
function params(extra={}){const query=new URLSearchParams({days:$('#filter-days').value,actor:$('#filter-actor').value,...extra});for(const [name,value] of [...query])if(!value)query.delete(name);return query;}
async function api(path,signal){const response=await fetch('/api/admin/operations/'+path,{credentials:'same-origin',cache:'no-store',signal:signal||AbortSignal.timeout(15000)});const result=await response.json();if(!response.ok){if(response.status===401||response.status===403){clearAuthSession();const user=await currentUser().catch(()=>null);if(!user)location.assign(loginURL('/admin/'));else if(user.role!=='admin'){authorized=false;clearInterval(timer);$('#admin-workspace').hidden=true;$('#access-message').hidden=false;$('#access-message').textContent='管理员会话已结束，请使用管理员账号重新登录。';}}throw Error(result.error?.message||'后台暂时无法连接。');}return result;}
function renderOverview(data,issues){
 const total=data.counts.reduce((sum,row)=>sum+row.count,0),completed=data.counts.filter(row=>row.status==='succeeded').reduce((sum,row)=>sum+row.count,0),running=data.counts.filter(row=>['planning','submitting','queued','running'].includes(row.status)).reduce((sum,row)=>sum+row.count,0);
 const scopedUsers=$('#filter-actor').value?data.users.filter(user=>user.id===$('#filter-actor').value):data.users;const storageUsed=scopedUsers.reduce((sum,user)=>sum+user.used,0),enabled=scopedUsers.filter(user=>user.enabled).length;
 const cards=[['生成任务',number(total),'已完成 '+number(completed)+' · 处理中 '+number(running),''],['需要关注',number(data.issues),'包含失败、待核对和备用封面',data.issues?'warn':'good'],['AI 接口调用',number(data.activity.aiCalls),'文本 Token '+number(data.activity.promptTokens+data.activity.completionTokens),''],['当前存储使用',size(storageUsed),number(enabled)+' 个启用账号 · 含系统素材','']];
 $('#summary-cards').innerHTML=cards.map(([title,value,note,tone])=>'<article class="summary-card"><span class="metric-title">'+esc(title)+'</span><strong class="metric-value '+tone+'">'+esc(value)+'</strong><span class="metric-note">'+esc(note)+'</span></article>').join('');
 const health=data.health,sync=health.sync,backup=health.backup;
 const syncStatus=sync.enabled?(sync.lastError?'error':!sync.lastFinishedAt?'warn':Date.now()-Date.parse(sync.lastFinishedAt)>120000?'warn':'ok'):'unavailable';
 $('#service-health').innerHTML=serviceRow('应用服务','ok','已运行 '+uptime(health.application.uptimeSeconds)+' · 内存 '+size(health.application.memoryBytes))+
  serviceRow('数据库',health.database.status,health.database.status==='ok'?'数据库 '+size(health.database.bytes)+' · WAL '+size(health.database.walBytes):health.database.message)+
  serviceRow('NAS 媒体存储',health.nas.status,health.nas.message)+
  serviceRow('后台任务同步',syncStatus,sync.lastError||(sync.running?'正在同步结果。':'每 30 秒检查一次，最近处理 '+number(sync.processed)+' 个任务。'),sync.lastFinishedAt?'最近检查 '+date(sync.lastFinishedAt):'等待首次检查。')+
  serviceRow('自动备份',backup.status,backup.message,backup.lastSuccess?'最近成功 '+date(backup.lastSuccess)+' · '+number(backup.files)+' 个文件 · '+size(backup.bytes):'尚无成功记录。');
 $('#system-check-time').textContent=date(health.checkedAt);
 const notices=[];if(health.nas.status==='error')notices.push('NAS 存储异常');if(backup.status==='error'||backup.status==='warn')notices.push('备份需要检查');if(syncStatus==='error'||syncStatus==='warn')notices.push('后台同步需要检查');if(health.auditError)notices.push(health.auditError);if(data.activity.errors)notices.push('范围内有 '+number(data.activity.errors)+' 次错误记录');
 $('#attention-banner').hidden=!notices.length;$('#attention-banner').textContent=notices.join('；')+'。可到“操作与错误”查看详情。';
 const trend=data.trend.slice(-14),max=Math.max(1,...trend.map(day=>day.total));
 $('#activity-chart').innerHTML=trend.length?trend.map(day=>{const succeeded=Math.min(day.succeeded,day.total-day.issues),other=Math.max(0,day.total-succeeded-day.issues),height=Math.max(3,day.total/max*120);return '<div class="day-bar" title="'+esc(day.day+'：'+day.total+' 个任务，'+day.issues+' 项需关注')+'"><span class="day-count">'+day.total+'</span><div class="bar-stack" style="height:'+height+'px"><i class="bar-success" style="height:'+succeeded/day.total*100+'%"></i><i class="bar-issue" style="height:'+day.issues/day.total*100+'%"></i><i class="bar-pending" style="height:'+other/day.total*100+'%"></i></div><span class="day-label">'+esc(day.day.slice(5))+'</span></div>';}).join(''):empty('这个时间范围内没有任务','用户开始创作后，这里会显示任务动态。');
 $('#provider-status').innerHTML=data.providers.map(provider=>{const latest=provider.latest,tone=!provider.configured?'muted':latest?.level==='error'?'warn':latest?'good':'muted';return '<article class="provider-card"><div class="provider-title">'+esc(provider.name)+badge(!provider.configured?'未配置':latest?.level==='error'?'最近调用异常':latest?'最近调用正常':'已配置',tone)+'</div><p>'+esc(latest?'最近记录 '+date(latest.last_seen_at):provider.configured?'等待记录真实调用。':'请在服务器配置密钥。')+'</p><p>'+esc(latest?'HTTP '+(latest.status??'—')+(latest.code?' · 返回码 '+latest.code:''):'不会在此显示密钥。')+'</p></article>';}).join('');
 $('#recent-issues').innerHTML=renderTasks(issues.items,true);
 $('#recording-note').textContent='运行日志从 '+(data.recordingStartedAt?date(data.recordingStartedAt):'本次接入')+' 开始记录；更早的生成任务可在任务记录中查看。保留最近 90 天、最多 50,000 条。任务图最多显示最近 14 个有记录的日期。';
 window.dispatchEvent(new CustomEvent('sanzo-admin-user-snapshot',{detail:data.users}));const selected=$('#filter-actor').value;$('#filter-actor').innerHTML='<option value="">全部用户</option>'+data.users.map(user=>'<option value="'+esc(user.id)+'">'+esc(user.name||user.email)+(user.enabled?'':'（已停用）')+'</option>').join('');$('#filter-actor').value=selected;
}
function pagination(type,data){$('#'+(type==='events'?'event':'task')+'-count').textContent='共 '+number(data.total)+' 条'+(data.total?' · 第 '+(Math.floor(data.offset/pageSize)+1)+' 页':'');$('#'+type+'-prev').disabled=data.offset===0;$('#'+type+'-next').disabled=data.offset+data.limit>=data.total;}
function selectView(next){if(!['overview','tasks','events','accounts'].includes(next))next='overview';view=next;const labels={overview:['运行概览','查看后台正在做什么，以及有哪些事情需要关注。'],tasks:['任务记录','追踪音频、语音、乐谱与封面的处理结果。'],events:['操作与错误','按时间与用户回看真实操作、AI 调用和系统异常。'],accounts:['账号与存储','管理邀请、账号状态与每位用户的存储空间。']};$('#view-title').replaceChildren(document.createTextNode(labels[next][0]));const dot=document.createElement('span');dot.className='heading-dot';dot.textContent='.';$('#view-title').append(dot);$('#view-description').textContent=labels[next][1];document.querySelectorAll('[data-panel]').forEach(panel=>panel.hidden=panel.dataset.panel!==next);document.querySelectorAll('[data-view]').forEach(link=>link.setAttribute('aria-current',link.dataset.view===next?'page':'false'));if(authorized)void refresh();}
async function refresh({fresh=false}={}){
 if(!authorized||!active)return;if(busy){pending=true;return;}busy=true;pending=false;const ticket=++sequence;controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);$('#refresh-operations').disabled=true;
 try{
  const signal=controller.signal,[data,issues]=await Promise.all([api('overview?'+params(fresh?{fresh:'1'}:{}),signal),api('tasks?'+params({status:'issues',limit:'6'}),signal)]);
  if(ticket!==sequence)return;renderOverview(data,issues);
  if(view==='tasks'){const tasks=await api('tasks?'+params({status:$('#task-status').value,offset:String(taskOffset),limit:String(pageSize)}),signal);if(ticket!==sequence)return;$('#task-table').innerHTML=renderTasks(tasks.items);pagination('tasks',tasks);}
  if(view==='events'){const events=await api('events?'+params({level:$('#event-level').value,category:$('#event-category').value,offset:String(eventOffset),limit:String(pageSize)}),signal);if(ticket!==sequence)return;$('#event-table').innerHTML=renderEvents(events.items);pagination('events',events);}
  $('#last-updated').textContent='更新于 '+date(data.generatedAt);$('#connection-status').className='badge good';$('#connection-status').textContent='已连接';$('#operations-feedback').textContent='';
 }catch(error){if(ticket===sequence){$('#connection-status').className='badge error';$('#connection-status').textContent='连接异常';$('#operations-feedback').textContent=error.name==='AbortError'?'请求超时，已保留上次结果。请检查服务或网络后刷新。':error.message+' 已保留上次结果。';}}
 finally{clearTimeout(timeout);busy=false;$('#refresh-operations').disabled=false;if(pending)void refresh();}
}
$('#refresh-operations').addEventListener('click',()=>refresh({fresh:true}));
for(const id of ['filter-days','filter-actor','task-status','event-level','event-category'])$('#'+id).addEventListener('change',()=>{taskOffset=0;eventOffset=0;sequence++;controller?.abort();void refresh();});
for(const type of ['tasks','events'])for(const direction of ['prev','next'])$('#'+type+'-'+direction).addEventListener('click',()=>{const delta=direction==='next'?pageSize:-pageSize;if(type==='tasks')taskOffset=Math.max(0,taskOffset+delta);else eventOffset=Math.max(0,eventOffset+delta);void refresh();});
$('#show-issue-tasks').addEventListener('click',()=>{$('#task-status').value='issues';taskOffset=0;});
window.addEventListener('hashchange',()=>selectView(location.hash.slice(1)));
window.addEventListener('sanzo-admin-changed',()=>refresh());
fetch('/api/auth/options',{cache:'no-store'}).then(response=>response.ok?response.json():Promise.reject()).then(options=>{$('#registration-policy').textContent=options.registrationOpen?'公开注册已开放，新用户可直接注册。':'目前采用邀请制。';}).catch(()=>{$('#registration-policy').textContent='注册方式暂时无法读取。';});
$('#export-diagnostics').addEventListener('click',async()=>{const button=$('#export-diagnostics');button.disabled=true;try{const result=await api('export?'+params(view==='tasks'?{status:$('#task-status').value}:view==='events'?{level:$('#event-level').value,category:$('#event-category').value}:{}));const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='sanzo-diagnostics-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){$('#operations-feedback').textContent=error.message;}finally{button.disabled=false;}});
function startTimer(){clearInterval(timer);timer=setInterval(()=>{if(!document.hidden&&$('#auto-refresh').checked&&!busy&&!taskOffset&&!eventOffset)void refresh();},30000);}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&$('#auto-refresh').checked)void refresh();});
window.addEventListener('pagehide',()=>{active=false;clearInterval(timer);sequence++;controller?.abort();});
window.addEventListener('pageshow',event=>{if(event.persisted){active=true;startTimer();void refresh();}});
try{const user=await currentUser();if(!user){location.assign(loginURL('/admin/'));}else if(user.role!=='admin'){$('#access-message').hidden=false;$('#access-message').textContent='此工具仅对管理员开放。请返回网站或使用管理员账号登录。';}else{authorized=true;$('#admin-identity').textContent=user.email;$('#admin-workspace').hidden=false;selectView(location.hash.slice(1));startTimer();document.documentElement.dataset.adminReady='true';window.dispatchEvent(new CustomEvent('sanzo-admin-ready'));}}
catch{$('#access-message').hidden=false;$('#access-message').textContent='暂时无法验证管理员身份，请刷新或重新登录。';}
